"use client";

import { Search } from "lucide-react";
import { usePathname, useRouter, useSearchParams } from "next/navigation";
import { useEffect, useState } from "react";

import { Input } from "@/components/ui/input";
import { Select } from "@/components/ui/select";

export function MentorsFilter() {
  const router = useRouter();
  const pathname = usePathname();
  const searchParams = useSearchParams();
  const searchValue = searchParams.get("search") ?? "";
  const publishedValue = searchParams.get("isPublished") ?? "all";
  const [search, setSearch] = useState(searchValue);

  useEffect(() => {
    setSearch(searchValue);
  }, [searchValue]);

  function updateParams(nextSearch: string, isPublished: string) {
    const params = new URLSearchParams(searchParams.toString());
    params.set("page", "1");

    if (nextSearch) {
      params.set("search", nextSearch);
    } else {
      params.delete("search");
    }

    if (isPublished !== "all") {
      params.set("isPublished", isPublished);
    } else {
      params.delete("isPublished");
    }

    const query = params.toString();
    router.replace(query ? `${pathname}?${query}` : pathname, {
      scroll: false,
    });
  }

  function clearFilters() {
    setSearch("");
    router.replace(pathname, { scroll: false });
  }

  return (
    <div className="mt-6 flex flex-col gap-3 sm:flex-row">
      <label className="relative flex-1">
        <Search
          aria-hidden="true"
          size={16}
          className="pointer-events-none absolute left-3 top-1/2 -translate-y-1/2 text-muted"
        />
        <Input
          value={search}
          onChange={(event) => {
            const value = event.target.value;
            setSearch(value);
            updateParams(value, publishedValue);
          }}
          placeholder="Search mentors"
          aria-label="Search mentors"
          className="pl-9"
        />
      </label>
      <Select
        value={publishedValue}
        onChange={(event) => updateParams(search, event.target.value)}
        aria-label="Filter mentors by publication status"
        className="sm:w-44"
      >
        <option value="all">All mentors</option>
        <option value="true">Published</option>
        <option value="false">Unpublished</option>
      </Select>
      <button
        type="button"
        onClick={clearFilters}
        className="h-10 cursor-pointer px-4 text-sm text-muted hover:text-primary"
      >
        Clear
      </button>
    </div>
  );
}